            inst_s5_th_desc: "設定項目",
            inst_s5_r1: "ローカルのタイムゾーンとサマータイム設定を指定します。",
            inst_s5_r2: "表示名 (<strong>Display name</strong>)、<strong>User name</strong>、<strong>PC name</strong>、ワークグループを入力します。",
